    bt_trash6_2: ['|Вы покинули мусорный контейнер и забыли о нём.'],
    bt_trash7_1: ['|Ого! Вы глубоко заботитесь о каждом мусорном контейнере, с которым взаимодействуете... Верно! Их 5. Этот мусорный контейнер счастлив, и даже мусор в нём стал красивым.', { flag: 'bt_t7' }, { give: { credits: 800 } }],
